import axios from "axios";
import MaterialTable from "material-table";
import React, { Component } from "react";
import { connect } from "react-redux";
import { Spinner } from "reactstrap";
import { tokenConfig } from "../../actions/authActions";
import store from "../../store";

class Clients extends Component {
  state = {
    rowData: [],
    clientsLoaded: false
  };

  componentDidMount() {
    this.retrieveClients();
  }

  retrieveClients = () => {
    this.setState(state => ({
      clientsLoaded: false,
      rowData: state.rowData
    }));
    axios
      .get("/api/clients")
      .then(res => {
        var rowData = res.data.map((x, index) => {
          return {
            id: x._id,
            name: x.name,
            created_by: x.createdByUserId.name
          };
        });
        this.setState(state => ({
          clientsLoaded: true,
          rowData
        }));
      })
      .catch(err => console.log(err));
  };

  onPageChangeClick = page => {
    //this.props.changePage(page);
    console.log(page);
  };

  render() {
    return (
      <div>
        {this.state.clientsLoaded ? (
          <MaterialTable
            columns={[
              { title: "ID", field: "id", editable: "never" },
              { title: "Name", field: "name" },
              {
                title: "Created By",
                field: "created_by",
                editable: "never",
                initialEditValue: this.props.auth.isAuthenticated
                  ? this.props.auth.user.name
                  : "Guest"
              }
            ]}
            data={this.state.rowData}
            title="Clients"
            options={{
              actionsColumnIndex: 3,
              addRowPosition: "first"
            }}
            onRowClick={(rowdata, event) => {
              //console.log(event.id);
              {
                this.onPageChangeClick.bind(this, event.id);
              }
            }}
            editable={{
              onRowAdd: newData =>
                new Promise((resolve, reject) => {
                  setTimeout(() => {
                    {
                      const newClient = {
                        name: newData.name,
                        userId: this.props.auth.isAuthenticated
                          ? this.props.auth.user._id
                          : "Guest"
                      };
                      axios
                        .post(
                          "/api/clients",
                          newClient,
                          tokenConfig(store.getState)
                        )
                        .then(res => {
                          console.log(res.data);
                          this.retrieveClients();
                        })
                        .catch(err => console.log(err.data));
                    }
                    resolve();
                  }, 10);
                }),
              onRowUpdate: (newData, oldData) =>
                new Promise((resolve, reject) => {
                  setTimeout(() => {
                    {
                      axios
                        .put(
                          `/api/clients/${newData.id}`,
                          { name: newData.name },
                          tokenConfig(store.getState)
                        )
                        .then(res => {
                          console.log(res.data);
                          this.retrieveClients();
                        })
                        .catch(err => console.log(err.data));
                    }
                    resolve();
                  }, 1000);
                }),
              onRowDelete: oldData =>
                new Promise((resolve, reject) => {
                  setTimeout(() => {
                    {
                      console.log(oldData.id);
                      axios
                        .delete(
                          `/api/clients/${oldData.id}`,
                          tokenConfig(store.getState)
                        )
                        .then(res => {
                          console.log(res.data);
                          this.retrieveClients();
                        })
                        .catch(err => console.log(err.data));
                    }
                    resolve();
                  }, 1000);
                })
            }}
          />
        ) : (
          <div
            style={{
              display: "flex",
              justifyContent: "center"
            }}
          >
            <Spinner animation="border" />
          </div>
        )}
      </div>
    );
  }
}

const mapStateToProps = state => ({
  //posts is from the root reducer. Items is from the postReducer, which is ultimately getting the action from the postAction.  This expression then allows for use of this.props.posts
  auth: state.auth
});

//export default connect(mapStateToProps, {postClient,getClients,deleteClient})(Clients);
export default connect(mapStateToProps, null)(Clients);
